'use strict';
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
function readStore(store,key,fallback){try{return JSON.parse(store.getItem(key))??fallback;}catch{return fallback;}}
let config=readStore(localStorage,'voyager-config',{});
let token=sessionStorage.getItem('voyager-access')||'';
let snapshot=null, connected=false, jobs=[], mode='query', polling=false, timer=null, sending=false;
let pending=readStore(sessionStorage,'voyager-pending',null);
let modelInfo=null;
const launchAccess=new URLSearchParams(location.hash.slice(1)).get('access');
if(launchAccess&&launchAccess.length>=32){token=launchAccess;config={...config,url:location.origin};sessionStorage.setItem('voyager-access',token);localStorage.setItem('voyager-config',JSON.stringify(config));history.replaceState(null,'',location.pathname+location.search);}
const activeStates=['QUEUED','PREPARING','GENERATING','REVIEWING','COMMITTING','AWAITING_CONFIRMATION','RECOVERY_REQUIRED'];
const labels={QUEUED:'等待处理',PREPARING:'正在读取场景',GENERATING:'AI 正在构思',REVIEWING:'正在复核剧情',AWAITING_CONFIRMATION:'待你确认',COMMITTING:'正在保存',SAVED:'已提交存档',ANSWERED:'问询已完成',NEEDS_INFORMATION:'需要补充信息',BLOCKED:'未通过校验',FAILED:'本轮未完成',INTERRUPTED:'生成已中断',STALE:'存档已变化',CANCELLED:'草案已放弃',RECOVERY_REQUIRED:'需要恢复原回合'};
const errors={NEW_PROVIDER_REQUIRES_KEY:'更换接口地址时，请重新填写相应提供商的 API Key。',MODEL_KEY_AND_ID_REQUIRED:'请填写 API Key 和模型名称。',FINISH_ACTIVE_TURN_BEFORE_MODEL_CHANGE:'请先完成、放弃或恢复当前回合，再修改模型配置。',AUTH_REQUIRED:'访问口令不正确，请检查连接设置。',SERVER_ACCESS_TOKEN_NOT_CONFIGURED:'服务器尚未配置游戏访问口令。',MODEL_NOT_CONFIGURED:'服务器尚未配置模型 API 密钥和模型 ID。',MODEL_SCHEMA_INVALID:'模型返回的内容格式不完整，本轮没有提交，请重新提出请求。',MODEL_HTTP_402:'DeepSeek 余额不足，请在提供商控制台充值后重试。',MODEL_HTTP_401:'模型服务鉴权失败，请检查服务器的 API 密钥。',MODEL_HTTP_429:'模型服务限流或额度不足，请稍后重试并检查额度。',MODEL_NETWORK_OR_TIMEOUT:'模型连接超时，本轮未自动重新生成。',ACTION_REQUIRES_ACTOR:'请在连接设置中填写视角人物 ID。',TURN_ALREADY_ACTIVE:'已有回合正在处理，请先完成或放弃当前草案。',SAVE_CHANGED_PREPARE_AGAIN:'存档已变化，请重新准备这一回合。',INDEPENDENT_REVIEW_FAILED:'独立剧情复核未通过，这份草案没有提交。',GENERATION_INTERRUPTED_RETRY_WITH_NEW_REQUEST:'服务器在生成期间重启。本轮没有自动重发模型请求。',ORIGIN_NOT_ALLOWED:'服务器未允许此网页地址，请配置 VOYAGER_ALLOWED_ORIGINS。',LIVING_PLAYER_CONTROL_REQUIRED:'当前人物尚未绑定为玩家视角，请先建立场景与视角。'};
function errorText(e){return errors[e]||e||'连接失败，请检查服务器地址与网络。';}
function el(tag,className,text){const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n;}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,4500);}
function fmt(v){return typeof v==='number'?v.toLocaleString('zh-CN'):(v??'—');}
function money(v){const [whole,fraction]=String(v??'—').split('.');return whole.replace(/\B(?=(\d{3})+(?!\d))/g,',')+(fraction!==undefined?'.'+fraction:'');}
function date(v){return v?String(v).replace('T',' ').replace(/:00$/,''):'—';}
function selectTab(tab){const titles={command:['指挥台','Command deck'],fleet:['舰队','Fleet overview'],tasks:['任务','Operations'],log:['航志','Voyage log']};if(!titles[tab])return;$$('.view').forEach(n=>n.classList.toggle('active-view',n.id===tab+'-view'));$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.tab===tab));$('#page-label').textContent=titles[tab][0];$('#page-title').replaceChildren(document.createTextNode(titles[tab][0]),el('span','',titles[tab][1]));window.scrollTo({top:0,behavior:'smooth'});}
function setMode(next){mode=next;$$('.mode').forEach(n=>n.classList.toggle('active',n.dataset.mode===next));$('#mode-hint').textContent=next==='query'?'查询信息，不推进游戏时间':'先生成行动草案，确认后执行';}
function setConnection(){const n=$('#connection');n.classList.toggle('live',connected);n.replaceChildren(el('i'),document.createTextNode(connected?'服务器已连接':'存档预览'));$('#channel-state').textContent=connected?'已接通游戏服务器':'等待连接';$('#send').disabled=!connected||sending||jobs.some(j=>activeStates.includes(j.status));$('#export-save').disabled=!connected;$('#source-label').textContent=(snapshot?.version||'V14.66')+' / '+(connected?'在线存档':'存档预览');$('#composer-status').textContent=!connected?'连接服务器后启用 AI 回合':pending?'待恢复发送，请重试原指令':'每轮进展自动保存';$('#preview-note').textContent=connected?(snapshot?.scenes?.current?.scene_id?'已连接。问询不走表；行动按实际耗时推进。':'当前没有开放场景。先选定视角人物和地点，建立新的游玩场景。'):'当前为 V14.66 存档预览。连接服务器后，可调用 AI 并保存新的游戏进展。';}
function renderState(s){snapshot=s;const core=s.core?.value?.fleet_core||{};const tasks=s.tasks?.value||[];$('#game-time').textContent=date(s.game_time);$('#save-version').textContent=s.version;$('#ship-total').textContent=fmt(['voyager','jinchuan','shadow'].reduce((n,k)=>n+(core[k]?.ships||0),0));$('#people-total').textContent=fmt(['voyager','jinchuan','shadow'].reduce((n,k)=>n+(core[k]?.personnel||0),0));$('#task-total').textContent=tasks.length;$('#task-badge').textContent=String(tasks.length).padStart(2,'0');$('#save-caption').textContent=connected?'服务器上的正式游戏进展':'来自你上传的正式存档';
  $('#fleet-cards').replaceChildren(...['voyager','jinchuan','shadow'].map((k,i)=>{const d=core[k]||{},card=el('article','fleet-card');card.append(el('div','eyebrow',['VOYAGER FLEET','JINCHUAN FLEET','SHADOW FLEET'][i]),el('h3','',d.display_name||k));const stats=el('div','fleet-stat');for(const [value,label]of [[d.ships,'在役舰船 / 艘'],[d.personnel,'舰队人员 / 人']]){const box=el('div');box.append(el('strong','',fmt(value)),el('span','',label));stats.append(box);}card.append(stats);return card;}));
  const accountNames={main_gold:'舰队主账户 · 金币',main_grey:'舰队主账户 · 灰币',covert_copper:'隐蔽账户 · 铜币',covert_grey:'隐蔽账户 · 灰币',shop_copper:'余火咖啡 · 铜币'};$('#accounts').replaceChildren(...Object.entries(s.accounts?.value||{}).map(([key,d])=>{const row=el('div','account-row'),left=el('div');left.append(el('span','',accountNames[key]||key));if(d.balance_evidence?.contains_authorized_simulation)left.append(el('small','','含已接受的模拟账目，未核实实物现金'));row.append(left,el('strong','',money(d.amount)));return row;}));
  $('#task-preview').replaceChildren(...tasks.slice(0,4).map(t=>{const n=el('div','mini-task');n.append(el('p','',t.title));const small=el('small');small.append(el('i'),document.createTextNode(t.next_review_at?'下一节点 '+date(t.next_review_at).slice(5):'等待指挥官指令'));n.append(small);return n;}));
  $('#task-list').replaceChildren(...tasks.map(t=>{const n=el('article','task-card'),h=el('header');h.append(el('h3','',t.title),el('span','status-pill',t.requires_ai_review?'需要关注':'执行中'));n.append(h,el('p','',t.next_review_at?'下一节点：'+date(t.next_review_at):'按指挥官指令处理'));const b=el('button','','询问这项任务 ↗');b.onclick=()=>fillPrompt('汇报“'+t.title+'”的当前状态与下一步需要处理的事项。','query');n.append(b);return n;}));setConnection();}
function reportText(job){if(job.status==='SAVED'){const r=job.result?.report;if(typeof r?.prose==='string')return r.prose;if(job.kind==='setup')return '场景设定已正式保存。你可以继续下达行动，生成接下来的故事。';return '这一回合已提交。机械结果以存档回执为准。';}return job.message||errorText(job.error)||labels[job.status];}
function renderJobs(){const list=$('#messages');list.replaceChildren();if(!jobs.length){const n=el('article','message welcome');n.append(el('div','message-label','舰载终端'),el('h3','','欢迎回来，指挥官。'),el('p','',connected?'舰队已接通。你可以先查询近况，或选定人物和地点开启新的场景。':'你的舰队与历史已经就位。连接游戏服务器后，便可继续这一段远航。'));list.append(n);}for(const job of jobs){const u=el('article','message user');u.append(el('div','message-label','指挥官 · '+(job.request.mode==='query'?'问询':'行动')),el('p','',job.request.intent));list.append(u);const n=el('article','message');n.append(el('div','message-label',job.status==='AWAITING_CONFIRMATION'?'AI 行动草案 · 尚未发生':'舰载终端 · '+(labels[job.status]||job.status)));if(job.message||job.status==='SAVED')n.append(el('p','',reportText(job)));if(job.error)n.append(el('p','error',errorText(job.error)));if(job.review?.status==='FAIL')n.append(el('p','error',(job.review.reasons||[]).join('；')));if(job.status==='SAVED')n.append(el('div','message-meta','存档回执已记录 · '+job.id.slice(-8)));list.append(n);}
  const active=jobs.find(j=>activeStates.includes(j.status));const controls=$('#turn-controls');controls.replaceChildren();if(active){if(active.status==='AWAITING_CONFIRMATION'){const card=el('div','turn-card');card.append(el('h3','','确认这一回合'),el('p','','以下设定或行动尚未执行。确认后由引擎校验并写入存档。'));if(active.kind==='turn')card.append(el('p','','游戏耗时：'+active.payload.elapsed_seconds+' 秒；机械效果：'+(active.payload.effects?.length||0)+' 项。'));else card.append(el('p','','场景与设定变更：'+(active.payload.actions?.length||0)+' 项，不推进游戏时间。'));const details=el('details'),summary=el('summary','','查看完整行动与设定');details.append(summary,el('pre','',JSON.stringify(active.payload,null,2)));card.append(details);const actions=el('div','turn-actions'),yes=el('button','primary','执行这一回合 ↗'),no=el('button','text-button','放弃草案');yes.onclick=()=>actOnJob(active,'confirm',{plan_hash:active.plan_hash});no.onclick=()=>actOnJob(active,'cancel',{});actions.append(yes,no);card.append(actions);controls.append(card);}else if(active.status==='RECOVERY_REQUIRED'){const card=el('div','turn-card');card.append(el('h3','','恢复原回合'),el('p','','结果需要重新核对。恢复会沿用原回合编号，不重新生成剧情或执行一份新行动。'));const b=el('button','primary','核对并恢复');b.onclick=()=>actOnJob(active,'recover',{});card.append(b);controls.append(card);}else controls.append(el('div','processing',labels[active.status]+'。切换页面后可继续查看结果。'));}
  const last=jobs.at(-1);if(last?.choices?.length&&!active){const bar=el('div','quick-actions');for(const text of last.choices){if(typeof text!=='string')continue;const b=el('button','',text);b.onclick=()=>fillPrompt(text,last.request.mode);bar.append(b);}controls.append(bar);}
  $('#log-list').replaceChildren(...(jobs.length?[...jobs].reverse().map(j=>{const n=el('article','log-entry');n.append(el('small','',new Date(j.created_at*1000).toLocaleString('zh-CN')+' · '+(labels[j.status]||j.status)),el('p','',j.request.intent));if(j.status==='SAVED')n.append(el('small','','已写入正式存档 · '+j.id));return n;}):[el('p','empty','还没有网页回合记录。连接服务器后，新的选择会记录在这里。')]));setConnection();}
async function api(path,options={},override){const cfg=override||{url:config.url||location.origin,token};const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(cfg.url+path,{...options,headers:{'Authorization':'Bearer '+cfg.token,...(options.body?{'Content-Type':'application/json'}:{}),...options.headers},signal:controller.signal,cache:'no-store',credentials:cfg.url===location.origin?'same-origin':'omit'});if(!response.ok){let e={};try{e=await response.json();}catch{}const err=new Error(errorText(e.error)||'服务器连接失败');err.code=e.error;err.detail=e.detail;throw err;}if(path==='/api/export')return await response.blob();return await response.json();}catch(e){if(e.name==='AbortError')throw new Error('服务器响应超时。请保留当前回合编号并重新连接。');throw e;}finally{clearTimeout(timeout);}}
async function refresh(){if(!connected||polling||document.hidden)return;polling=true;try{const next=await api('/api/turns');const changed=JSON.stringify(jobs)!==JSON.stringify(next);jobs=next;if(pending&&jobs.some(j=>j.id===pending.client_id)){pending=null;sessionStorage.removeItem('voyager-pending');}if(changed){renderJobs();if(jobs.at(-1)?.status==='SAVED')renderState(await api('/api/state'));}}catch(e){$('#channel-state').textContent='连接中断，可重新连接';if(e.code==='AUTH_REQUIRED'){connected=false;setConnection();}}finally{polling=false;}}
async function connect(url,key){const status=await api('/api/status',{}, {url,token:key});const [state,turns]=await Promise.all([api('/api/state',{}, {url,token:key}),api('/api/turns',{}, {url,token:key})]);config={...config,url};token=key;connected=true;jobs=turns;localStorage.setItem('voyager-config',JSON.stringify(config));sessionStorage.setItem('voyager-access',key);renderState(state);renderJobs();try{modelInfo=await api('/api/model-settings');}catch{modelInfo=null;}if(!status.model_configured)toast('请在设置中填写模型 API。');else toast('已接通你的远航。');return status;}
function fillPrompt(text,nextMode){selectTab('command');setMode(nextMode);$('#intent').value=text;$('#intent').focus();$('#composer').scrollIntoView({behavior:'smooth',block:'center'});}
async function actOnJob(job,action,body){$$('#turn-controls button').forEach(b=>b.disabled=true);try{await api('/api/turns/'+job.id+'/'+action,{method:'POST',body:JSON.stringify(body)});await refresh();}catch(e){toast(e.message);await refresh();$$('#turn-controls button').forEach(b=>b.disabled=false);}}
$$('[data-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));$$('.mode').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$$('[data-prompt]').forEach(b=>b.onclick=()=>fillPrompt(b.dataset.prompt,b.dataset.mode));
function applyDeepseekPreset(){$('#model-base').value='https://api.deepseek.com';$('#model-id').value='deepseek-flash';$('#review-model').value='';$('#model-protocol').value='responses';}
$('#deepseek-preset').onclick=applyDeepseekPreset;
function openSettings(){const d=$('#settings');$('#server-url').value=config.url||'';$('#access-token').value=token;$('#actor-id').value=config.actor_id||'';$('#scene-id').value=config.scene_id||'';$('#settings-error').textContent='';$('#model-section').hidden=!connected;$('#connection-fields').classList.toggle('codespaces',connected&&location.hostname.endsWith('.app.github.dev'));$('#model-base').value=modelInfo?.base_url||'https://api.openai.com/v1';$('#model-id').value=modelInfo?.model_id||'';$('#review-model').value=modelInfo?.review_model_id||'';$('#model-protocol').value=modelInfo?.protocol||'responses';if(!modelInfo?.model_id&&!modelInfo?.key_saved)applyDeepseekPreset();$('#model-key').value='';$('#model-key-note').textContent=modelInfo?.key_saved?'服务器已保存密钥；留空保留原密钥。':'仅发送到你的游戏后端，不保存在浏览器或提交到 GitHub。';if(!d.open)d.showModal();}
$$('.settings-open').forEach(b=>b.onclick=openSettings);$('.close-dialog').onclick=()=>$('#settings').close();$('#settings').addEventListener('click',e=>{if(e.target===$('#settings')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#settings-form').onsubmit=async e=>{e.preventDefault();const b=$('#connect-button');b.disabled=true;$('#settings-error').textContent='';try{const u=new URL($('#server-url').value.trim()||location.origin);if(u.username||u.password||u.search||u.hash||u.pathname!=='/')throw new Error('请填写服务器根地址，例如 https://game.example.com');if(u.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(u.hostname))throw new Error('手机连接需要 HTTPS 游戏服务器地址。');const key=$('#access-token').value.trim();if(key.length<32)throw new Error('游戏访问口令至少需要 32 个字符。');config={...config,actor_id:$('#actor-id').value.trim(),scene_id:$('#scene-id').value.trim()};const entered={api_key:$('#model-key').value.trim(),base_url:$('#model-base').value.trim(),model_id:$('#model-id').value.trim(),review_model_id:$('#review-model').value.trim(),protocol:$('#model-protocol').value};const status=await connect(u.origin,key);const changed=!!entered.api_key||['base_url','model_id','protocol'].some(k=>entered[k]!==modelInfo?.[k])||(entered.review_model_id||entered.model_id)!==(modelInfo?.review_model_id||modelInfo?.model_id||'');if(changed&&entered.model_id){modelInfo=await api('/api/model-settings',{method:'POST',body:JSON.stringify(entered)});$('#model-key').value='';toast('模型配置已保存，可以开始游玩。');}else if(!status.model_configured){openSettings();throw new Error('请填写 API Key 和模型名称，然后保存。');}$('#settings').close();}catch(ex){$('#settings-error').textContent=ex.message;}finally{b.disabled=false;}};
$('#disconnect').onclick=()=>{connected=false;token='';sessionStorage.removeItem('voyager-access');jobs=[];pending=null;sessionStorage.removeItem('voyager-pending');$('#access-token').value='';$('#settings').close();loadSnapshot();toast('已断开服务器。');};
$('#composer').onsubmit=async e=>{e.preventDefault();if(!connected){openSettings();return;}if(sending)return;const text=$('#intent').value.trim();if(!text)return;if(mode==='action'&&!config.actor_id){toast('请先在连接设置中填写视角人物 ID。');openSettings();return;}if(pending&&pending.intent!==text){toast('上一次发送结果尚未确认，请先重新连接并核对原回合。');return;}sending=true;setConnection();const request=pending||{client_id:'WEB-'+crypto.randomUUID(),intent:text,mode,actor_id:config.actor_id||null,scene_id:config.scene_id||null};pending=request;sessionStorage.setItem('voyager-pending',JSON.stringify(request));try{await api('/api/turns',{method:'POST',body:JSON.stringify(request)});pending=null;sessionStorage.removeItem('voyager-pending');$('#intent').value='';await refresh();}catch(ex){if(ex.code){pending=null;sessionStorage.removeItem('voyager-pending');}toast(ex.message);}finally{sending=false;setConnection();}};
$('#intent').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();$('#composer').requestSubmit();}});
$('#start-scene').onclick=()=>fillPrompt('我想建立一个全新的独立游玩场景。请先核对视角人物与地点，列出必要的新人物背景、环境和开场设定草案，等我确认后再保存。','action');
$('#export-save').onclick=async()=>{try{const blob=await api('/api/export');const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='VOYAGER_'+(snapshot?.version||'SAVE')+'_WEB.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('存档已导出。');}catch(e){toast(e.message);}};
async function loadSnapshot(){try{const response=await fetch('snapshot.json',{cache:'no-store',headers:token?{Authorization:'Bearer '+token}:{}});if(!response.ok)throw new Error();renderState(await response.json());renderJobs();}catch{setConnection();$('#preview-note').textContent='请连接游戏服务器，读取你的舰队与当前存档。';}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});window.addEventListener('online',refresh);setInterval(refresh,2500);
loadSnapshot().then(async()=>{if(token){try{const status=await connect(config.url||location.origin,token);if(!status.model_configured)openSettings();}catch{$('#channel-state').textContent='请检查连接设置';}}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
